StepWizard.example:
import * as React from "react";
import { Input, StepWizard } from "@sutra/ui";

export function Example({ onCreate }: { onCreate: () => Promise<void> }) {
  const [name, setName] = React.useState("");
  const steps = [
    {
      id: "workspace",
      title: "Workspace",
      content: <Input aria-label="Workspace name" value={name} onChange={(event) => setName(event.target.value)} />,
    },
    { id: "review", title: "Review", content: <p>Create the workspace “{name}”?</p> },
  ];
  return (
    <StepWizard
      steps={steps}
      canAdvance={(step) => step.id !== "workspace" || name.trim() !== ""}
      onComplete={onCreate}
      labels={{ finish: "Create workspace" }}
    />
  );
}

Steps.example:
import * as React from "react";
import { Button, Steps } from "@sutra/ui";

const steps = [
  { title: "Account", description: "Create your login" },
  { title: "Workspace", description: "Name your team" },
  { title: "Invite", description: "Add teammates" },
];

export function Example() {
  const [current, setCurrent] = React.useState(1);
  return (
    <div className="max-w-xl space-y-4">
      <Steps steps={steps} current={current} onStepClick={setCurrent} />
      <div className="flex gap-2">
        <Button variant="outline" disabled={current === 0} onClick={() => setCurrent(current - 1)}>
          Back
        </Button>
        <Button disabled={current === steps.length} onClick={() => setCurrent(current + 1)}>
          {current === steps.length - 1 ? "Finish" : "Continue"}
        </Button>
      </div>
    </div>
  );
}

SutraMascot.example:
import { SutraMascot, mascotStateLabels, type MascotCharacter, type MascotState } from "@sutra/ui";

export function Example({ phase, character }: { phase: "waiting" | "working" | "answering" | "failed"; character: MascotCharacter }) {
  const state: MascotState =
    phase === "working" ? "working" : phase === "answering" ? "speaking" : phase === "failed" ? "error" : "idle";
  return (
    <div className="flex items-center gap-3">
      <SutraMascot character={character} shape="circle" size={36} state={state} />
      <p role="status" className="text-sm text-muted-foreground">
        {mascotStateLabels[state]}
      </p>
    </div>
  );
}

