ToggleGroup.example:
import * as React from "react";
import { ToggleGroup, ToggleGroupItem } from "@sutra/ui";
import { RiBold, RiItalic, RiUnderline } from "@sutra/ui/icons";

export function Example() {
  const [marks, setMarks] = React.useState<string[]>(["bold"]);
  return (
    <ToggleGroup
      type="multiple"
      variant="outline"
      aria-label="Text formatting"
      value={marks}
      onValueChange={setMarks}
    >
      <ToggleGroupItem value="bold" aria-label="Bold">
        <RiBold aria-hidden />
      </ToggleGroupItem>
      <ToggleGroupItem value="italic" aria-label="Italic">
        <RiItalic aria-hidden />
      </ToggleGroupItem>
      <ToggleGroupItem value="underline" aria-label="Underline">
        <RiUnderline aria-hidden />
      </ToggleGroupItem>
    </ToggleGroup>
  );
}

Tooltip.example:
import { Button, SimpleTooltip, Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@sutra/ui";
import { RiDeleteBinLine, RiSave3Line } from "@sutra/ui/icons";

export function Example() {
  return (
    <TooltipProvider>
      <div className="flex items-center gap-2">
        <SimpleTooltip content="Save" shortcut="mod+s">
          <Button size="icon" variant="outline" aria-label="Save">
            <RiSave3Line aria-hidden />
          </Button>
        </SimpleTooltip>
        <Tooltip>
          <TooltipTrigger asChild>
            <Button size="icon" variant="outline" aria-label="Delete">
              <RiDeleteBinLine aria-hidden />
            </Button>
          </TooltipTrigger>
          <TooltipContent side="bottom">Delete permanently</TooltipContent>
        </Tooltip>
      </div>
    </TooltipProvider>
  );
}

TransferList.example:
import { TransferList, type TransferItemData } from "@sutra/ui";

const MB = 1024 * 1024;
const transfers: TransferItemData[] = [
  { id: "1", name: "photos.zip", direction: "upload", status: "active", bytes: 20 * MB, total: 80 * MB, speed: 4 * MB },
  { id: "2", name: "report.pdf", direction: "download", status: "failed", error: "Connection lost" },
  { id: "3", name: "notes.txt", direction: "upload", status: "completed", total: MB },
];

type Props = { onCancel: (id: string) => void; onRetry: (id: string) => void; onClear: () => void };

export function Example({ onCancel, onRetry, onClear }: Props) {
  return <TransferList items={transfers} onCancel={onCancel} onRetry={onRetry} onClearCompleted={onClear} />;
}

